mapper.select:
SELECT COUNT(1) FROM ( SELECT CAMPAIGN_ID, CAMPAIGN_NAME, SEND_TYPE, STATUS, TOTAL_CNT, SUCCESS_CNT, FAIL_CNT, PENDING_CNT, SUCCESS_RATE FROM V_SMS_STAT
WHERE SEND_TYPE = #{SEND_TYPE}
ORDER BY CAMPAIGN_ID ) A

SELECT * FROM (
    SELECT A.*, ROWNUM AS RNUM FROM (
        SELECT X.* FROM (
            SELECT CAMPAIGN_ID, CAMPAIGN_NAME, SEND_TYPE, STATUS,
                   TOTAL_CNT, SUCCESS_CNT, FAIL_CNT, PENDING_CNT, SUCCESS_RATE
            FROM   V_SMS_STAT


                WHERE SEND_TYPE = #{SEND_TYPE}

            ORDER  BY CAMPAIGN_ID
        ) X

    ) A WHERE ROWNUM <= #{offset} + #{size}
) WHERE RNUM > #{offset}
